"""Payment presentation and interaction regression against original DOS frames."""
from pathlib import Path
from io import BytesIO
import argparse,base64,hashlib,json,struct
from PIL import Image,ImageChops
from playwright.sync_api import sync_playwright
ROOT=Path(__file__).resolve().parents[2];DATA=ROOT/'testing/output/treehouse'

def verify(html,output):
    output.mkdir(parents=True,exist_ok=False);report=dict(demo_sha256=hashlib.sha256(html.read_bytes()).hexdigest(),checks=[],pixels={},errors=[])
    with sync_playwright()as p:
        browser=p.chromium.launch(channel='msedge',headless=True);page=browser.new_page();page.add_init_script('requestAnimationFrame=()=>0');page.on('pageerror',lambda e:report['errors'].append(str(e)));page.goto(html.resolve().as_uri());page.evaluate("resident.ambientEnabled=false;setScene('boardgame')")
        path=DATA/'research-board-audit/native/state/payment-wait';ram=path.with_suffix('.ram-0').read_bytes();ds=0x323f0;words=lambda at,n=1:list(struct.unpack_from('<'+str(n)+'h',ram,at));py,px=words(ds+0x2064,2)
        model=dict(mode=1,opponent=2,options=False,phase='result',player=words(ds+0x52d8)[0],nodes=words(ds+0x52c4,2),directions=words(ds+0x5734,2),balances=words(ds+0x5a0c,2),types=words(ds+0x59da,24),remaining=-1,rewards=[-4],paymentRequested=4,paidChips=[2]*4,message="You need to get a new driver's license.",moving=None,played=True,transfer=None,exchange=None,winner=-1,loser=-1,paymentHand=dict(id=4301,palette=4300,x=232,y=119,clip=[98,226,194,320]))
        page.evaluate('m=>{boardgame.motion.cancel();Object.assign(boardgame,m);}',model);page.evaluate('p=>{treehouseDemo.setPointer(...p);render();}',[px,py])
        image=Image.open(BytesIO(base64.b64decode(page.locator('#game').evaluate('c=>c.toDataURL()').split(',')[1]))).convert('RGB');ref=Image.open(path.with_suffix('.png')).convert('RGB');delta=ImageChops.difference(image,ref);n=sum(a!=b for a,b in zip(image.getdata(),ref.getdata()));report['pixels']['chip-payment']=dict(exact=n==0,different_pixels=n,bounds=delta.getbbox());image.save(output/'chip-payment.png');delta.save(output/'chip-payment-difference.png')
        path=DATA/'research-board-audit-money/native/state/payment-settled';ram=path.with_suffix('.ram-0').read_bytes();py,px=words(ds+0x2064,2)
        model.update(mode=0,player=words(ds+0x52d8)[0],nodes=words(ds+0x52c4,2),directions=words(ds+0x5734,2),balances=words(ds+0x5a0c,2),types=words(ds+0x59da,24),rewards=[-1],rewardCoins=[[0,0,0,0,0,1]],paymentRequested=1,paidChips=[],paymentCoinsVisible=True,message='Your gas tank is empty. Fill it up.',paymentHand=dict(id=4301,palette=4300,x=232,y=29,clip=[19,226,102,320]))
        page.evaluate('m=>Object.assign(boardgame,m)',model);page.evaluate('p=>{treehouseDemo.setPointer(...p);render();}',[px,py])
        image=Image.open(BytesIO(base64.b64decode(page.locator('#game').evaluate('c=>c.toDataURL()').split(',')[1]))).convert('RGB');ref=Image.open(path.with_suffix('.png')).convert('RGB');delta=ImageChops.difference(image,ref);n=sum(a!=b for a,b in zip(image.getdata(),ref.getdata()));report['pixels']['money-payment']=dict(exact=n==0,different_pixels=n,bounds=delta.getbbox());image.save(output/'money-payment.png');delta.save(output/'money-payment-difference.png')
        page.evaluate('boardgame.mode=1')
        def check(name,code):report['checks'].append(dict(name=name,passed=bool(page.evaluate(code))))
        page.evaluate('window.finishBoard=()=>{for(let i=0;i<30000&&boardgame.motion.busy;i++){if(boardgame.exchange)boardgame.exchangeChips();advance();if(i%20===0)render();}return !boardgame.motion.busy;};')
        check('chip payment delivers hand before subtracting and retains paid chips','()=>{const g=boardgame;g.paymentHand=null;g.paidChips=[];g.paymentRequested=4;g.paymentLoser=-1;g.rewards=[-4];g.startTransfer(25,-4);const initially=g.balances[g.player]===25&&g.paidChips.length===0;return finishBoard()&&initially&&g.balances[g.player]===21&&g.paidChips.length===4&&g.paymentHand?.id===4301;}')
        check('exchange rejects options and accepts only original stack','()=>{const g=boardgame;g.paidChips=[];g.rewards=[-1];g.paymentRequested=1;g.startTransfer(10,-1);for(let i=0;i<1000&&!g.exchange;i++)advance();if(!g.exchange)return false;const r=g.tables.chip_rects[0];g.click(r[1]+1,r[0]+1);g.showOptions();if(g.options||g.motion.accepted)return false;const s=g.tables.chip_rects[1+g.exchange.digit];g.click(s[1]+1,s[0]+1);return g.motion.accepted&&finishBoard()&&g.balances[g.player]===9;}')
        check('money payment conceals coins until bag reaches hand','()=>{const g=boardgame;g.mode=0;g.paymentLoser=-1;g.paymentRequested=3;g.rewards=[-3];g.paymentCoinsVisible=false;g.motion.start(g.motion.moneyDebit(3,10));const hidden=!g.paymentCoinsVisible&&g.balances[g.player]===10;return finishBoard()&&hidden&&g.balances[g.player]===7&&g.paymentCoinsVisible&&g.paymentHand?.id===4301;}')
        check('zero balance Chips still receive payment hand with no extra wait','()=>{const g=boardgame;g.mode=1;g.paymentHand=null;g.paidChips=[];g.paymentRequested=4;g.paymentLoser=g.player;g.rewards=[-4];g.startTransfer(0,-0);const immediate=g.motion.sprite?.id===4301;return finishBoard()&&immediate&&g.balances[g.player]===0&&g.paidChips.length===0&&g.paymentHand?.id===4301&&g.loser===g.player;}')
        check('zero balance Money keeps requested caption without payment hand','()=>{const g=boardgame;g.mode=0;g.paymentHand=null;g.paymentLoser=g.player;g.paymentRequested=3;g.rewards=[-3];g.paymentCoinsVisible=false;g.motion.start(g.motion.moneyDebit(3,0));return finishBoard()&&g.rewards[0]===-3&&!g.paymentHand&&!g.paymentCoinsVisible&&g.loser===g.player;}')
        check('native seeded mystery landing preserves amounts narrative and RNG','()=>{const g=boardgame;g.motion.cancel();g.mode=1;g.player=0;g.levels=[0,0];g.nodes[0]=8;g.types[8]=25;g.seed=0xfb9450ba;g.land();const ok=JSON.stringify(g.rewards)==="[4,2]"&&g.message==="You drove a neighbor to the store!"&&g.seed===0xf93e33e9&&g.rewardCoins.length===0;g.motion.cancel();return ok;}')
        check('landing conceals offers through narrative speech','()=>{const g=boardgame;g.types[g.nodes[g.player]]=24;g.land();const first=g.headerHidden&&g.motion.panels===0;advance(30);const spoken=!g.headerHidden&&g.motion.panels===0&&g.motion.speaking;g.motion.cancel();return first&&spoken;}')
        check('ordinary input skips current board speech','()=>{const g=boardgame;g.motion.start(g.motion.say(11163));const pending=g.motion.speaking&&g.motion.due>g.tick;g.click(160,100);advance();return pending&&!g.motion.busy&&!g.motion.speaking;}')
        check('offer reminder flashes each pane at twelve ticks','()=>{const g=boardgame;g.motion.start(g.motion.reminder("reward"));const first=g.offerHint===0;advance(12);const second=g.offerHint===1;advance(12);return first&&second&&g.offerHint===-1&&!g.motion.busy;}')
        check('movement reminder visits legal neighbors in adjacency order','()=>{const g=boardgame;g.motion.start(g.motion.reminder("move"));const out=[];while(g.motion.busy){out.push(g.nodeHint);advance(12);}return JSON.stringify(out)===JSON.stringify(g.neighbours())&&g.nodeHint===-1;}')
        check('choice during a flashing reminder starts the requested transfer','()=>{const g=boardgame;g.mode=0;g.phase="reward";g.rewards=[2,3];g.rewardCoins=[[0,0,0,0,0,2],[0,0,0,0,0,3]];g.motion.start(g.motion.reminder("reward"));g.choose(1);const ok=g.phase==="selection"&&g.chosen===1&&!g.motion.reminding&&g.offerHint===-1;g.motion.cancel();return ok;}')
        check('human movement flashes target and retains die until twelve ticks after arrival','()=>{const g=boardgame;g.motion.cancel();g.phase="move";g.options=false;g.player=0;g.opponent=1;g.nodes[0]=7;g.remaining=1;g.moving=null;const next=g.neighbours()[0];g.move(next);const flash=g.nodeHint===next&&!g.moving;advance(11);const held=g.nodeHint===next&&!g.moving;advance();const moving=!!g.moving&&g.nodeHint===-1;for(let i=0;i<1000&&!g.moving?.arrived;i++)advance();const arrival=g.remaining===1;advance(11);const pause=g.remaining===1;advance();const result=g.remaining===0&&g.nodes[0]===next;g.motion.cancel();return flash&&held&&moving&&arrival&&pause&&result;}')
        report['passed']=not report['errors']and all(c['passed']for c in report['checks'])and all(v['exact']for v in report['pixels'].values());browser.close()
    (output/'report.json').write_text(json.dumps(report,indent=2),encoding='utf-8');print(json.dumps(report,indent=2))

if __name__=='__main__':
    p=argparse.ArgumentParser(description=__doc__);p.add_argument('--html',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args();verify(a.html,a.output)
